    hitokoto: "\u8D9F\u7740\u6CEA\u6CB3\u3002",
    type: "f",
    from: "\u7CBE\u536B\uFF08\u4E07\u7269\u7EC8\u5F52\u5411\u6D77\uFF09",
    from_who: null,
